// TMDD organ membership: liver=1, heart=4, gut=8.
fn tmdd_is_organ(i: i64) -> bool {
    if i == 1 { return true }
    if i == 4 { return true }
    if i == 8 { return true }
    return false
}

// Baseline R_free at no-drug steady state, nmol/L.
fn tmdd_rtotal0_at(i: i64) -> f64 {
    if i == 1 { return 50.0 }
    if i == 4 { return 25.0 }
    if i == 8 { return 30.0 }
    return 0.0
}

fn tmdd_kdeg_at(i: i64) -> f64 { return 0.05 }                 // 1/h, R-turnover
fn tmdd_kon_at(i: i64)  -> f64 { return 0.10 }                 // L/(nmol·h)
fn tmdd_kd_at(i: i64)   -> f64 { return 0.10 }                 // nmol/L (K_d = k_off/k_on)
fn tmdd_kint_at(i: i64) -> f64 { return 0.010 }                // 1/h, DR internalization

fn tmdd_koff_at(i: i64) -> f64 { return tmdd_kon_at(i) * tmdd_kd_at(i) }
fn tmdd_ksyn_at(i: i64) -> f64 { return tmdd_kdeg_at(i) * tmdd_rtotal0_at(i) }

fn pbpk_invariant_report(result: SimulationResult) -> PbpkInvariantReport with Mut {
    var out = pbpk_invariant_report_empty()

    out.non_negative_state = state_non_negative(result.final_state)
    out.finite_outputs =
        finite_like(result.cmax) && finite_like(result.auc) && finite_like(result.half_life) &&
        finite_like(result.clearance) && finite_like(result.vdss) && state_finite(result.final_state)

    // Reference case 1 is IV bolus: concentration should not increase above Cmax at end.
    out.route_constraints_ok = result.cmax >= result.final_state.blood && result.final_state.blood >= 0.0

    out.success = result.success && out.non_negative_state && out.finite_outputs && out.route_constraints_ok
    out
}

